import * as vercel from "@pulumiverse/vercel";

const example = new vercel.AuditLogDrain("example", {
    name: "security-audit-events",
    http: {
        endpoint: "https://siem.example.com/vercel",
        encoding: "ndjson",
        compression: "gzip",
        headers: {
            Authorization: "Bearer my-secret-token",
        },
    },
});
```
