// exists in a `ui` directory and any terraform exists in a `terraform` directory.
// E.g.
// ```
// ui/
//    src/
//        index.js
//    package.json
//    // etc...
// terraform/
//    main.tf
// ```
const filesExample = vercel.getProjectDirectory({
    path: "../ui",
});
const filesExampleGetProject = vercel.getProject({
    name: "my-awesome-project",
});
const filesExampleDeployment = new vercel.Deployment("files_example", {
    projectId: filesExampleGetProject.then(filesExampleGetProject => filesExampleGetProject.id),
    files: filesExample.then(filesExample => filesExample.files),
    pathPrefix: filesExample.then(filesExample => filesExample.path),
    production: true,
    environment: {
        FOO: "bar",
    },
});
//# Or deploying a specific commit or branch
