const exampleFirewallConfig = new vercel.FirewallConfig("example", {
    projectId: example.id,
    rules: {
        rules: [
            {
                name: "Bypass Known request",
                description: "Bypass requests using internal bearer tokens",
                conditionGroups: [
                    {
                        conditions: [{
                            type: "header",
                            key: "Authorization",
                            op: "eq",
                            value: "Bearer internaltoken",
                        }],
                    },
                    {
                        conditions: [{
                            type: "header",
                            key: "Authorization",
                            op: "eq",
                            value: "Bearer internaltoken2",
                        }],
                    },
                ],
                action: {
                    action: "bypass",
                },
            },
            {
                name: "Challenge curl",
                description: "Challenge user agents containing 'curl'",
                conditionGroups: [{
                    conditions: [{
                        type: "user_agent",
                        op: "sub",
                        value: "curl",
                    }],
                }],
                action: {
                    action: "challenge",
                },
            },
            {
                name: "Deny cookieless requests",
                description: "requests to /api that are missing a session cookie",
                conditionGroups: [{
                    conditions: [
                        {
                            type: "path",
                            op: "eq",
                            value: "/api",
                        },
                        {
                            type: "cookie",
                            key: "_session",
                            neg: true,
                            op: "ex",
                        },
                    ],
                }],
                action: {
                    action: "challenge",
                },
            },
            {
                name: "Require Authorization header",
                description: "Block requests without Authorization header",
                conditionGroups: [{
                    conditions: [{
                        type: "header",
                        key: "Authorization",
                        op: "nex",
                    }],
                }],
                action: {
                    action: "deny",
                },
            },
            {
                name: "Log requests with custom header",
                description: "Log requests that have X-Custom-Header present",
                conditionGroups: [{
                    conditions: [{
                        type: "header",
                        key: "X-Custom-Header",
                        op: "ex",
                    }],
                }],
                action: {
                    action: "log",
                },
            },
            {
                name: "Rate limit API",
                description: "apply ratelimit to requests under /api",
                conditionGroups: [{
                    conditions: [{
                        type: "path",
                        op: "pre",
                        value: "/api",
                    }],
                }],
                action: {
                    action: "rate_limit",
                    rateLimit: {
                        limit: 100,
                        window: 300,
                        keys: [
                            "ip",
                            "ja4",
                        ],
                        algo: "fixed_window",
                        action: "deny",
                    },
                    actionDuration: "5m",
                },
            },
            {
                name: "Known clients",
                description: "Match known keys in header",
                conditionGroups: [{
                    conditions: [{
                        type: "header",
                        key: "Authorization",
                        op: "inc",
                        values: [
                            "key1",
                            "key2",
                        ],
                    }],
                }],
                action: {
                    action: "rate_limit",
                    rateLimit: {
                        limit: 100,
                        window: 300,
                        keys: [
